              "type": "number"
            },
            "height": {
              "type": "number"
            }
          },
          "required": [
            "width",
            "height"
          ],
          "additionalProperties": false
        }
      },
      "additionalProperties": false
    },
    "parsers": {
      "type": "array",
      "items": {
        "type": "string",
        "enum": [
          "pdf"
