      "additionalProperties": false
    },
    "onlyMainContent": {
      "type": "boolean"
    },
    "redactPII": {
      "type": "boolean"
    },
    "includeTags": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "excludeTags": {
      "type": "array",
      "items": {
        "type": "string"
      }
    },
    "waitFor": {
      "type": "number"
    },
    "actions": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "type": {
            "type": "string",
            "enum": [
              "wait",
              "screenshot",
              "scroll",
              "scrape",
              "click",
              "write",
              "press",
              "executeJavascript",
              "generatePDF"
            ]
          },
          "selector": {
            "type": "string"
          },
          "milliseconds": {
            "type": "number"
          },
          "text": {
            "type": "string"
          },
          "key": {
            "type": "string"
          },
          "direction": {
            "type": "string",
            "enum": [
              "up",
              "down"
            ]
          },
          "script": {
            "type": "string"
          },
          "fullPage": {
            "type": "boolean"
          }
        },
        "required": [
          "type"
        ],
        "additionalProperties": false
      }
    },
    "mobile": {
      "type": "boolean"
    },
    "skipTlsVerification": {
      "type": "boolean"
    },
    "removeBase64Images": {
      "type": "boolean"
    },
    "location": {
      "type": "object",
      "properties": {
        "country": {
          "type": "string"
        },
        "languages": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      },
      "additionalProperties": false
    },
    "storeInCache": {
      "type": "boolean"
    },
    "zeroDataRetention": {
      "type": "boolean"
    },
    "maxAge": {
      "type": "number"
